mapper.select:
SELECT count(*)
FROM function_permissions
WHERE screen_id = #{screenId}
  AND role_code = #{roleCode}
  AND function_type = #{functionType}
  AND permission_allowed = 'ALLOW'

SELECT count(*)
FROM evaluation_element_management_item_settings
WHERE evaluation_year = #{evaluationYear}
  AND management_item_code = #{managementItemCode}
  AND active_yn = 'Y'
  AND effective_start_date <= #{occurredDate}
  AND effective_end_date >= #{occurredDate}

SELECT count(*)
FROM evaluation_finalizations
WHERE target_user_id = #{ownerUserId}
  AND evaluation_year = #{evaluationYear}
  AND final_status = 'EVALUATION_CONFIRMED'

SELECT count(*)
FROM lecture_evaluation_achievements achievement
WHERE achievement.achievement_id = #{achievementId}
  AND achievement.deleted_yn = 'N'
  AND (
      achievement.owner_user_id = #{userId}
      OR EXISTS (
          SELECT 1
          FROM organization_user_mappings mapping
          WHERE mapping.user_id = #{userId}
            AND mapping.organization_code = achievement.organization_code
            AND mapping.status = 'ACTIVE'
            AND mapping.effective_start_date <= CURRENT_DATE
            AND (mapping.effective_end_date IS NULL OR mapping.effective_end_date >= CURRENT_DATE)
      )
  )

mapper.update:
UPDATE lecture_evaluation_achievements
SET certification_status = #{nextStatus}, updated_at = CURRENT_TIMESTAMP, updated_by = #{updatedBy}
WHERE achievement_id = #{achievementId}
  AND certification_status = #{previousStatus}
  AND deleted_yn = 'N'

mapper.insert:
INSERT INTO education_achievement_status_histories (
    achievement_type, achievement_id, previous_status, next_status, action_type, reason_code, opinion, processed_by
) VALUES (
    #{achievementType}, #{achievementId}, #{previousStatus}, #{nextStatus}, #{actionType}, #{reasonCode}, #{opinion}, #{processedBy}
)

INSERT INTO data_change_histories (
    target_business, target_key, change_type, field_name, before_value, after_value, changed_by, change_reason
) VALUES (
    #{targetBusiness}, #{targetKey}, #{changeType}, #{fieldName}, #{beforeValue}, #{afterValue}, #{changedBy}, #{changeReason}
)
